// Fixed campaign. See games-src/campaigns.md for design and regeneration.
fn campaign(level: i32) -> (Stand, i32) {
    let (rows, par): (&[[u8; CAP]], i32) = match level {
        0 => (&[[1, 1, 2, 2], [2, 2, 1, 1], [0, 0, 0, 0]], 3),                                                           // Level 1
        1 => (&[[1, 2, 2, 2], [2, 1, 1, 1], [0, 0, 0, 0]], 3),                                                           // Level 2
        2 => (&[[1, 2, 1, 2], [2, 1, 2, 1], [0, 0, 0, 0]], 8),                                                           // Level 3
        3 => (&[[1, 2, 2, 1], [2, 1, 1, 2], [0, 0, 0, 0]], 5),                                                           // Level 4
        4 => (&[[1, 1, 2, 1], [2, 2, 1, 2], [0, 0, 0, 0]], 5),                                                           // Level 5
        5 => (&[[1, 1, 2, 2], [2, 3, 3, 1], [3, 1, 3, 2], [0, 0, 0, 0]], 9),                                             // Level 6
        6 => (&[[3, 1, 2, 1], [3, 2, 2, 3], [1, 2, 3, 1], [0, 0, 0, 0]], 11),                                            // Level 7
        7 => (&[[3, 2, 3, 1], [2, 1, 2, 1], [3, 2, 1, 3], [0, 0, 0, 0]], 12),                                            // Level 8
        8 => (&[[2, 3, 2, 3], [1, 2, 1, 3], [1, 2, 3, 1], [0, 0, 0, 0]], 12),                                            // Level 9
        9 => (&[[2, 3, 2, 1], [3, 1, 2, 3], [1, 2, 1, 3], [0, 0, 0, 0]], 12),                                            // Level 10
        10 => (&[[3, 1, 4, 2], [3, 1, 3, 3], [1, 2, 2, 2], [4, 4, 4, 1], [0, 0, 0, 0]], 10),                             // Level 11
        11 => (&[[1, 3, 3, 2], [1, 4, 3, 2], [4, 4, 3, 1], [4, 1, 2, 2], [0, 0, 0, 0]], 13),                             // Level 12
        12 => (&[[2, 4, 3, 4], [3, 2, 1, 2], [1, 2, 1, 3], [4, 4, 3, 1], [0, 0, 0, 0]], 15),                             // Level 13
        13 => (&[[3, 2, 1, 4], [4, 2, 4, 3], [1, 2, 4, 1], [3, 1, 3, 2], [0, 0, 0, 0]], 16),                             // Level 14
        14 => (&[[1, 3, 2, 4], [4, 1, 2, 3], [2, 4, 3, 1], [2, 1, 4, 3], [0, 0, 0, 0]], 16),                             // Level 15
        15 => (&[[3, 1, 4, 1], [3, 4, 4, 4], [5, 2, 2, 2], [1, 1, 3, 5], [5, 5, 3, 2], [0, 0, 0, 0]], 12),               // Level 16
        16 => (&[[2, 4, 5, 3], [3, 5, 1, 1], [2, 2, 2, 4], [1, 1, 3, 5], [3, 4, 4, 5], [0, 0, 0, 0]], 14),               // Level 17
        17 => (&[[2, 3, 1, 3], [5, 5, 2, 5], [1, 3, 4, 4], [1, 4, 3, 1], [4, 2, 2, 5], [0, 0, 0, 0]], 17),               // Level 18
        18 => (&[[2, 3, 2, 5], [4, 3, 5, 1], [1, 5, 3, 4], [2, 4, 4, 1], [2, 5, 3, 1], [0, 0, 0, 0]], 18),               // Level 19
        19 => (&[[5, 2, 4, 1], [3, 2, 3, 4], [3, 5, 2, 5], [4, 1, 5, 1], [4, 1, 2, 3], [0, 0, 0, 0]], 20),               // Level 20
        20 => (&[[2, 1, 5, 5], [1, 2, 2, 3], [4, 4, 6, 3], [6, 2, 5, 5], [4, 4, 6, 1], [1, 3, 3, 6], [0, 0, 0, 0]], 14), // Level 21
        21 => (&[[1, 6, 6, 6], [4, 3, 2, 2], [2, 2, 4, 4], [6, 5, 1, 5], [4, 5, 5, 3], [3, 1, 3, 1], [0, 0, 0, 0]], 14), // Level 22
        22 => (&[[3, 4, 2, 3], [6, 2, 3, 1], [1, 3, 4, 5], [6, 6, 6, 2], [1, 1, 2, 4], [5, 5, 5, 4], [0, 0, 0, 0]], 18), // Level 23
        23 => (&[[2, 3, 2, 3], [4, 4, 4, 6], [1, 5, 2, 6], [5, 6, 1, 5], [1, 2, 5, 1], [3, 3, 4, 6], [0, 0, 0, 0]], 21), // Level 24
        24 => (&[[3, 6, 5, 5], [1, 3, 5, 6], [4, 6, 1, 2], [1, 2, 3, 4], [3, 5, 4, 2], [1, 4, 2, 6], [0, 0, 0, 0]], 22), // Level 25
        25 => (&[[6, 3, 5, 6], [4, 4, 6, 5], [2, 5, 7, 1], [4, 4, 6, 3], [3, 2, 2, 3], [1, 1, 7, 1], [5, 2, 7, 7], [0, 0, 0, 0]], 21), // Level 26
        26 => (&[[3, 3, 5, 3], [7, 7, 1, 3], [6, 2, 2, 5], [6, 6, 1, 7], [2, 4, 4, 2], [1, 5, 4, 1], [7, 5, 6, 4], [0, 0, 0, 0]], 21), // Level 27
        27 => (&[[7, 2, 1, 7], [7, 3, 1, 2], [2, 5, 5, 4], [5, 5, 7, 2], [4, 1, 3, 3], [6, 6, 1, 6], [6, 4, 4, 3], [0, 0, 0, 0]], 21), // Level 28
        28 => (&[[1, 6, 4, 6], [3, 6, 3, 2], [7, 7, 7, 6], [7, 1, 2, 1], [1, 4, 5, 4], [5, 3, 2, 2], [4, 5, 5, 3], [0, 0, 0, 0]], 19), // Level 29
        29 => (&[[1, 5, 1, 4], [7, 3, 7, 7], [4, 4, 5, 4], [3, 2, 3, 6], [2, 6, 2, 2], [7, 6, 5, 1], [3, 6, 5, 1], [0, 0, 0, 0]], 23), // Level 30

        _ => unreachable!("campaign level"),
    };
    let mut s = Stand::empty(rows.len() as i32);
    s.tube[..rows.len()].copy_from_slice(rows);
    (s, par)
}
